  if(s.type==='optionprofile')return figure(s.title,A.optionProfile(s),(s.reference_close!==undefined?'옵션·당시 현물 수집 '+s.retrieved_at+' · 참고 종가일 '+s.price_date:'이전 계산 현물 종가일 '+s.price_date+' · 옵션 수집 '+s.retrieved_at+' · 자료 시점이 다를 수 있음')+' · '+s.expiries.join(', ')+' · 보존 관측·딜러 부호 가정');
  if(s.type==='gauges')return heading(s.title)+`<div class="indicator-grid">${s.items.map(a=>{const value=typeof a.value==='number',position=value?Math.max(0,Math.min(100,100*(a.value-a.min)/(a.max-a.min))):0,colors=['#3c8c80','#c4a047','#c97755','#b76272'];return `<article class="panel indicator-card"><h3>${E(a.name)}</h3><strong class="indicator-value">${num(a.value)} <small>${E(a.unit)}</small></strong><div class="gauge-track" style="background:${a.value===null?'#b5bfc5':gaugeColor(a)}">${value?`<i style="left:${position}%"></i>`:''}${a.cuts.map(c=>`<span style="left:${100*(c-a.min)/(a.max-a.min)}%" title="관찰선 ${c}"></span>`).join('')}</div><div class="gauge-range"><span>${num(a.min)}</span><span>${num(a.max)}</span></div><p>${E(a.rule)}</p><small>관측 ${E(a.date||'자료 없음')}</small></article>`;}).join('')}</div>`;
  if(s.type==='industry')return heading(s.title)+`<div data-industries="${i}"><div class="analysis-controls"><label>산업 <select data-industry-filter><option value="all">전체13개 산업</option>${[...new Set(s.items.map(a=>a.sector))].map(g=>`<option>${E(g)}</option>`).join('')}</select></label><label>지표 역할 <select data-role-filter><option value="all">전체</option><option value="P">P 판가</option><option value="Q">Q 수요·생산</option><option value="C">C 원가</option><option value="S">S 시장심리</option></select></label></div><div class="indicator-grid">${s.items.map(a=>`<article class="panel indicator-card" data-industry="${E(a.sector)}" data-indicator-role="${a.role}"><small>${E(a.sector)} · ${a.role}</small><h3>${E(a.name)}</h3><strong class="indicator-value">${num(a.value)} <small>${E(a.unit)}</small></strong>${A.spark(a.spark,a.name+' · 3년')}<p>1개월 ${num(a.one_month)}${E(a.change_unit)} · 3개월 ${num(a.three_month)}${E(a.change_unit)}<br>3년 z ${num(a.z)} · ${E(a.signal)}</p><p class="quiet">${E(a.note)}</p><small>관측 ${E(a.date||'자료 없음')} · <a href="${E(a.source)}" target="_blank" rel="noopener noreferrer">${E(a.key)} ↗</a></small></article>`).join('')}</div></div>`;
  if(s.type==='hologram')return heading(s.title)+`<div data-hologram="${i}"><div class="projection-controls"><label>궤적 회전 <input data-holo-yaw type="range" min="-314" max="314" value="60"></label><label>확대 <input data-holo-zoom type="range" min="50" max="140" value="100"></label><button type="button" data-holo-reset>초기화</button></div><p class="chart-help">드래그 · ← → 회전 · +/− 확대 · Home 초기화</p><div class="hologram-grid"><div><div data-holo-canvas tabindex="0" role="group" aria-label="3D 궤적 회전 및 확대">${A.hologram(s)}</div><div class="projection-pan"><button type="button" data-holo-pan="-1">← 왼쪽 보기</button><button type="button" data-holo-pan="1">오른쪽 보기 →</button></div></div><div>${A.radar(s)}</div></div></div><details><summary>36개월5축 원수치·관측일</summary>${table({title:s.title+' · 원수치',columns:['관측일',...s.axes.map(a=>a.name+' '+a.unit)],rows:s.rows.map(r=>[r.date,...s.axes.map(a=>r.raw[a.key])])})}</details>`;
  if(s.type==='wordcloud'){const max=Math.max(1,...s.words.map(w=>w.count));return heading(s.title)+`<div class="word-cloud">${s.words.map(w=>`<span style="font-size:${14+24*w.count/max}px" title="기사 ${w.count}건">${E(w.term)} <small>${w.count}</small></span>`).join('')}</div>`;}
  if(s.type==='scenario')return heading(s.title)+`<div data-scenario="${i}"><div class="analysis-controls"><label>시장 <select data-scenario-market><option>KR</option><option>US</option></select></label><label>시장 충격 % <input data-shock type="number" min="-30" max="30" step="1" value="-10"></label></div><p class="quiet">예상 변화=최근252일 Beta×가정 충격. 인과 전파·확정 손익·실제 포트폴리오가 아닙니다.</p><div data-scenario-output></div></div>`;
  if(s.type==='table')return table(s);
