 function discoveryOutput(rows,limit){const metrics={r1m:'1M %',r3m:'3M %',r6m:'6M %',rs_z:'초과수익 z',accel:'3M−6M/2 %p',prox:'52주 고점 대비 %',vsurge:'거래량 5/20 배',eps_growth:'FY1 EPS 성장 %',surprise:'EPS 서프라이즈 %',analysts:'애널리스트 수',rating:'추천 1매수~5매도',upside:'목표가 여력 %'};return `<p role="status">${rows.length}개 후보 중 ${Math.min(limit,rows.length)}개 표시</p>`+rows.slice(0,limit).map((r,i)=>`<article class="panel discovery-row" data-discovery-symbol="${E(r.symbol)}"><div class="discovery-heading"><div><small>${i+1} · ${E(r.market)} · ${E(r.sector)} · ${E(r.bucket)}</small><h3>${E(r.name)} <small>${E(r.symbol)}</small></h3></div><div class="discovery-score"><strong>${num(r.score)}</strong><small>종합 / −3~+3</small><div class="score-track"><i style="width:${r.score===null?0:Math.abs(r.score)/3*50}%;left:${r.score<0?50-Math.abs(r.score)/3*50:50}%;background:${r.score<0?'#b96976':'#36937e'}"></i></div></div></div><div class="discovery-lenses">${[['tech','기술'],['fund','실적'],['smart','애널리스트']].map(([k,n])=>`<div data-discovery-lens="${k}" class="${r[k]===null?'lens-empty':r[k]>0?'lens-positive':r[k]<0?'lens-negative':''}"><span>${n}</span><b>${num(r[k])}</b></div>`).join('')}</div><div class="tags">${r.reasons.map(t=>`<span>${E(t)}</span>`).join('')}</div><details><summary>지표·선정 근거 자세히</summary><dl class="discovery-metrics">${Object.entries(metrics).map(([k,n])=>`<div><dt>${n}</dt><dd>${num(r.metrics[k])}</dd></div>`).join('')}</dl><p class="quiet">기술 구성 ${Object.entries(r.components).map(([k,v])=>E(k)+': '+num(v)).join(' · ')}<br>가격 ${E(r.price_date)} · 재무/애널리스트 ${E(r.financial_date||'자료 없음')}</p></details></article>`).join('')+(rows.length?'':'<p class="quiet">이 조건에 해당하는 공개 후보가 없습니다.</p>');}
 function bindSort(scope){scope.querySelectorAll('[data-sort]').forEach(b=>{if(b.dataset.sortBound)return;b.dataset.sortBound='1';b.addEventListener('click',()=>{const table=b.closest('table'),body=table.querySelector('tbody'),idx=+b.dataset.sort;const dir=b.dataset.direction==='desc'?1:-1;b.dataset.direction=dir===1?'asc':'desc';[...body.rows].sort((a,z)=>{const av=a.cells[idx]?.dataset.value||'',zv=z.cells[idx]?.dataset.value||'';if(av===''||zv==='')return av===''?1:-1;return dir*(Number.isFinite(Number(av))&&Number.isFinite(Number(zv))?Number(av)-Number(zv):av.localeCompare(zv,'ko'));}).forEach(r=>body.appendChild(r));});});}
